async function api(path,options={}){const headers={...options.headers};if(options.body&&!options.form)headers['Content-Type']='application/json';if(options.method&&options.method!=='GET'){headers['X-CSRF-Token']=S.csrf;headers['X-Idempotency-Key']=options.key||activeSubmitKey||id();}const response=await fetch(path,{credentials:'same-origin',...options,headers,body:options.form|| (options.body?JSON.stringify(options.body):undefined)});let data;try{data=await response.json();}catch{throw Error('服务返回了无效响应，请检查部署与网络');}if(!response.ok){const err=Error(data.error||'请求失败');err.code=data.code;err.status=response.status;throw err;}return data;}
async function act(type,data={},sensitive=false){if(sensitive)await reauth();const key=activeSubmitKey||id();const send=()=>api(`/api/projects/${S.project.id}/actions`,{method:'POST',body:{type,data},key});try{S.project=await send();}catch(err){if(err.code!=='REAUTH_REQUIRED')throw err;await reauth();S.project=await send();}if(S.project.removedFromProject){S.project=null;S.projects=(await api('/api/projects')).projects;toast('成员退出已生效，你已离开该项目');}await refreshSide();render();return S.project;}
