function setMenuOpen(open,restoreFocus=true){
 const nav=$('.sidebar'),trigger=$('[data-action="menu"]'),backdrop=$('.nav-backdrop'),main=$('.main');
 open=Boolean(open&&mobileLayout.matches&&nav);
 nav?.classList.toggle('open',open);
 document.body.classList.toggle('nav-open',open);
 if(main)main.inert=open;
 if(backdrop)backdrop.hidden=!open;
 trigger?.setAttribute('aria-expanded',String(open));
 if(nav){
  if(open){nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');}
  else{nav.removeAttribute('role');nav.removeAttribute('aria-modal');}
 }
 if(open)nav.querySelector('[data-action="close-menu"]')?.focus({preventScroll:true});
 else if(restoreFocus&&trigger&&mobileLayout.matches)trigger.focus({preventScroll:true});
}
mobileLayout.addEventListener('change',()=>setMenuOpen(false,false));
document.addEventListener('keydown',event=>{
 const nav=$('.sidebar.open');if(!nav)return;
 if(event.key==='Escape'){event.preventDefault();setMenuOpen(false);return;}
 if(event.key!=='Tab')return;
 const items=[...nav.querySelectorAll('button:not(:disabled),select,a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length);
 if(!items.length)return;
 const first=items[0],last=items.at(-1),current=document.activeElement;
 if(event.shiftKey&&(current===first||!nav.contains(current))){event.preventDefault();last.focus();}
 else if(!event.shiftKey&&(current===last||!nav.contains(current))){event.preventDefault();first.focus();}
});
function prepareResponsiveTables(root){
 for(const table of root.querySelectorAll('.table-wrap table')){
  const heads=[...table.querySelectorAll('thead th')];
  const rows=[...table.querySelectorAll('tbody tr')];
  // Keep complex merged tables as real, labelled horizontal scroll regions.
  const simple=heads.length&&rows.every(row=>row.cells.length===heads.length&&[...row.cells].every(cell=>cell.colSpan===1&&cell.rowSpan===1));
  const wrap=table.closest('.table-wrap');
  wrap.tabIndex=0;wrap.setAttribute('role','region');
  wrap.setAttribute('aria-label',table.closest('.panel')?.querySelector('h3')?.textContent||'明细表格，可横向滚动');
  if(!simple)continue;
  table.classList.add('mobile-cards');table.setAttribute('role','table');
  for(const row of table.rows)row.setAttribute('role','row');
  for(const head of heads){head.scope='col';head.setAttribute('role','columnheader');}
  for(const row of rows)for(let index=0;index<row.cells.length;index++){
   const cell=row.cells[index];cell.dataset.label=heads[index].textContent.trim()||'操作';cell.setAttribute('role','cell');
  }
 }
}
// Reveal is opt-in for account password fields only, never for tokens/Webhooks.
let passwordControlNumber=0;
function preparePasswordVisibility(dialog){
 for(const input of dialog.querySelectorAll('input[type="password"][data-password-reveal]')){
  if(input.closest('.password-control'))continue;
  const label=input.closest('.field')?.querySelector('label');
  const fieldName=input.dataset.passwordLabel||label?.textContent.trim()||'密码';
  if(!input.id)input.id='account-password-'+(++passwordControlNumber);
  if(label)label.htmlFor=input.id;
  input.setAttribute('autocapitalize','none');input.spellcheck=false;
  const wrap=document.createElement('div');wrap.className='password-control';
  input.before(wrap);wrap.appendChild(input);
  const toggle=document.createElement('button');toggle.type='button';toggle.className='btn password-toggle';
  toggle.setAttribute('aria-controls',input.id);
  const setVisible=visible=>{
   const start=input.selectionStart,end=input.selectionEnd,direction=input.selectionDirection;
   input.type=visible?'text':'password';
   toggle.textContent=visible?'隐藏':'显示';
   toggle.setAttribute('aria-label',(visible?'隐藏':'显示')+fieldName);
   if(start!==null&&end!==null)input.setSelectionRange(start,end,direction||'none');
  };
  setVisible(false);wrap.appendChild(toggle);
  toggle.addEventListener('click',()=>setVisible(input.type==='password'));
  // Submission still reads the same value; closing discards it from the dialog.
  const conceal=()=>setVisible(false);
  const form=input.closest('form');form?.addEventListener('submit',conceal);
  dialog.addEventListener('close',()=>{
   conceal();input.value='';form?.removeEventListener('submit',conceal);
  },{once:true});
 }
}
let accessibleDialogNumber=0;
function openAccessibleDialog(dialog){
 preparePasswordVisibility(dialog);
 const secretInputs=[...dialog.querySelectorAll('input[type="password"],input[data-password-reveal]')];
 dialog.addEventListener('close',()=>{for(const input of secretInputs){input.value='';input.type='password';}},{once:true});
 const heading=dialog.querySelector('.modal-head h2');
 if(heading){heading.id='dialog-title-'+(++accessibleDialogNumber);heading.tabIndex=-1;dialog.setAttribute('aria-labelledby',heading.id);}
 updateDialogViewport();dialog.showModal();
 // Do not unexpectedly open the on-screen keyboard before the user reads the form.
 heading?.focus({preventScroll:true});
}
function updateDialogViewport(){
 const view=window.visualViewport,style=document.documentElement.style;
 if(mobileLayout.matches&&view&&Math.abs(view.scale-1)<0.05){
  style.setProperty('--dialog-view-height',Math.round(view.height)+'px');
  style.setProperty('--dialog-view-top',Math.round(view.offsetTop)+'px');
 }else{style.removeProperty('--dialog-view-height');style.removeProperty('--dialog-view-top');}
}
window.visualViewport?.addEventListener('resize',updateDialogViewport);
window.visualViewport?.addEventListener('scroll',updateDialogViewport);
window.addEventListener('resize',updateDialogViewport);

