function editPlanForm(){const p=S.project;showForm('编辑筹备计划',[{name:'name',label:'项目名称',value:p.name,full:true},{name:'description',label:'项目情况与目标',value:p.description,type:'textarea',required:false,full:true},{name:'budget',label:'总预算（元）',value:amountInput(p.settings.totalBudgetCents),type:'money'},{name:'reserve',label:'最低保留资金（元）',value:amountInput(p.settings.minReserveCents),type:'money'},{name:'terms',label:'合作约定：出资、职责、决策、分配与退出',type:'textarea',value:p.settings.terms,full:true,rows:5},{name:'stages',label:'阶段计划',type:'html',full:true,html:`<div id="stage-rows" class="repeat-box">${(p.stages.length?p.stages:[{name:'小规模验证',budgetCents:Math.floor(p.settings.totalBudgetCents*.2),goal:'验证做法、制作流程、实际成本与成果',acceptance:'提交样片、原型或小规模试做结果，核对耗时、成本与待解决问题'},{name:'扩大执行',budgetCents:Math.floor(p.settings.totalBudgetCents*.8),goal:'依据验证结果决定是否扩大投入',acceptance:'全体合伙人确认阶段效果、资金安排和退出预案'}]).map(stageRow).join('')}</div><button type="button" class="btn small" data-add-stage>＋ 增加阶段</button>`}],async(a,fd)=>{const names=fd.getAll('stageName'),ids=fd.getAll('stageId'),budgets=fd.getAll('stageBudget'),goals=fd.getAll('stageGoal'),acceptances=fd.getAll('stageAcceptance'),ends=fd.getAll('stageEnd');const stages=names.map((name,i)=>({id:ids[i]||undefined,name,budgetCents:toCents(budgets[i]),goal:goals[i],acceptance:acceptances[i],startDate:p.stages.find(s=>s.id===ids[i])?.startDate||'',endDate:ends[i]}));await act('plan.update',{name:a.name,description:a.description,totalBudgetCents:toCents(a.budget),minReserveCents:toCents(a.reserve),terms:a.terms,stages});},{intro:'筹备期修改不会自动生效。全体合伙人确认基准后，后续关键修改必须走共同决策。'});}
