 if(kind==='member_remove'){fields=[{name:'memberId',label:'拟退出成员',type:'select',options:p.members.filter(m=>m.active&&m.userId!==p.ownerId).map(m=>[m.id,m.name]),value:preset.memberId}];payload=a=>({memberId:a.memberId});}
 if(kind==='terms'){fields=[{name:'terms',label:'新的完整合作约定',type:'textarea',value:p.settings.terms,full:true,rows:6}];payload=a=>({terms:a.terms});}
 if(['stage_open','stage_close'].includes(kind)){fields=[{name:'stageId',label:'目标阶段',type:'select',options:stageOptions(),value:preset.stageId},{name:'evidence',label:'验证结果 / 开放或验收依据',type:'textarea',full:true}];payload=a=>({stageId:a.stageId,evidence:a.evidence});}
 if(kind==='task_change'){const t=p.tasks.find(t=>t.id===preset.taskId)||p.tasks.find(t=>t.status!=='done');if(!t)throw Error('没有可变更的未完成任务');fields=[{name:'taskId',label:'目标任务',type:'select',options:p.tasks.filter(t=>t.status!=='done').map(t=>[t.id,t.title]),value:t.id},{name:'dueDate',label:'新的截止日期',type:'date',value:t.dueDate},{name:'assigneeId',label:'新的负责人',type:'select',options:mOptions(),value:t.assigneeId},{name:'reviewerId',label:'新的验收人',type:'select',options:mOptions(),value:t.reviewerId}];payload=a=>({taskId:a.taskId,dueDate:a.dueDate,assigneeId:a.assigneeId,reviewerId:a.reviewerId});}
 if(kind==='settlement'){fields=[{name:'amount',label:'本次拟分配金额（元）',type:'money',full:true},{name:'basis',label:'结算口径与未结事项说明',type:'textarea',full:true}];payload=a=>({amountCents:toCents(a.amount),basis:a.basis});}
 if(kind==='reconcile'){fields=[{name:'balance',label:'外部流水核对后的实际余额（元）',type:'money',value:amountInput(p.finance.verifiedCash),full:true},{name:'evidence',label:'外部账户与对账依据',type:'textarea',full:true}];payload=a=>({balanceCents:toCents(a.balance),evidence:a.evidence});}
 if(kind==='profit_rule'){sharesForm();return;}
