app.addEventListener('click',async event=>{const el=event.target.closest('button,[data-project]');if(!el)return;try{if(el.dataset.tab){await navigate(el.dataset.tab);return;}if(el.dataset.project){await selectProject(el.dataset.project);return;}if(el.dataset.action){el.disabled=true;await onAction(el.dataset.action,el);}}catch(err){if(err.message!=='已取消身份确认')toast(err.message,true);}finally{el.disabled=false;}});
app.addEventListener('change',async event=>{if(event.target.id==='project-picker'){try{if(event.target.value)await selectProject(event.target.value);else{S.project=null;S.adminMode=false;render();}}catch(err){toast(err.message,true);}}});
app.addEventListener('input',event=>{if(event.target.id==='purchase-search'){S.search=event.target.value;const pos=event.target.selectionStart;render();const input=$('#purchase-search');input.focus();input.setSelectionRange(pos,pos);}});
modal.addEventListener('click',async event=>{const extra=event.target.closest('[data-action^="security-"],[data-action^="continuity-"],[data-action^="supervision-"]');if(extra){try{await onAction(extra.dataset.action,extra);}catch(err){toast(err.message,true);}return;}const adminButton=event.target.closest('[data-action^="admin-"]');if(adminButton){try{await ADMIN.action(adminButton.dataset.action,adminButton);}catch(err){toast(err.message,true);}return;}if(event.target.closest('[data-modal-close]'))closeModal();if(event.target.closest('[data-add-item]'))$('#item-rows').insertAdjacentHTML('beforeend',itemRow());if(event.target.closest('[data-add-stage]'))$('#stage-rows').insertAdjacentHTML('beforeend',stageRow());if(event.target.closest('[data-remove-row]'))event.target.closest('.repeat-row').remove();if(event.target.closest('[data-copy-invite]')){try{await navigator.clipboard.writeText($('#invite-url').value);toast('邀请链接已复制，请私下发送');}catch{$('#invite-url').select();toast('请复制选中的邀请链接');}}});
modal.addEventListener('cancel',()=>{if(reauthReject){reauthReject(Error('已取消身份确认'));reauthReject=null;}});
modal.addEventListener('submit',async event=>{event.preventDefault();if(submitBusy||!formHandler)return;const form=event.target,handler=formHandler,fd=new FormData(form),key=formKey;submitBusy=true;activeSubmitKey=key;const submit=form.querySelector('button[type=submit]');submit.disabled=true;const oldText=submit.textContent;submit.textContent='正在提交…';$('#form-error').innerHTML='';try{await handler(Object.fromEntries(fd),fd);if(formHandler===handler){modal.close();toast('已保存');}}catch(err){const target=form.querySelector('#form-error');if(target){target.innerHTML=`<div class="field-error" role="alert">${e(err.message)}</div>`;target.scrollIntoView({block:'nearest'});}}finally{submitBusy=false;activeSubmitKey=null;submit.disabled=false;submit.textContent=oldText;}});

function renderPasswordRequired(){
 setMenuOpen(false,false);AI.stop();S.adminMode=false;
 app.innerHTML=`<main class="panel password-required"><div class="eyebrow">ACCOUNT SECURITY</div><h1>首次登录，请修改临时密码</h1><p>${e(S.user.username||S.user.email)}：修改完成前，不能访问项目或管理员功能。</p><form id="required-password-form">${fieldHtml({name:'current',label:'当前临时密码',type:'password',maxLength:128,revealPassword:true,autocomplete:'current-password'})}${fieldHtml({name:'password',label:'设置新密码（12–128字符）',type:'password',maxLength:128,revealPassword:true,autocomplete:'new-password'})}${fieldHtml({name:'confirm',label:'再次输入新密码',type:'password',maxLength:128,revealPassword:true,autocomplete:'new-password'})}<div id="required-password-error" role="alert"></div><div class="buttons"><button type="submit" class="btn primary">修改后进入</button><button type="button" class="btn" data-action="logout">退出登录</button></div></form></main>`;
 preparePasswordVisibility(app);
}
app.addEventListener('submit',async event=>{
 if(event.target.id!=='required-password-form')return;
 event.preventDefault();const form=event.target,a=Object.fromEntries(new FormData(form)),button=form.querySelector('[type="submit"]');button.disabled=true;
 try{
  if(a.password!==a.confirm)throw Error('两次输入的新密码不一致');
  if(a.password.length<12||a.password.length>128)throw Error('新密码须为12–128字符');
  if(a.current===a.password)throw Error('新密码不能与临时密码相同');
  if(S.user.mfaEnabled){const status=await api('/api/auth/mfa/status');if(!status.fresh)await SECURITY.verify();}
  await api('/api/auth/reauth',{method:'POST',body:{password:a.current}});
  await api('/api/auth/password',{method:'POST',body:{password:a.password}});
  form.reset();const me=await api('/api/auth/me');S.user=me.user;S.csrf=me.csrf;await afterLogin();toast('密码已修改，请妥善保管');
 }catch(err){const el=$('#required-password-error');if(el)el.textContent=err.message;}
 finally{button.disabled=false;}
});
function renderAuth(mode='login',invite=null){setMenuOpen(false,false);const joining=mode==='invite',setup=mode==='bootstrap';app.innerHTML=`<div class="auth-shell"><section class="auth-story"><div class="brand"><img src="/favicon.svg" alt=""><div><strong>合伙有序</strong><span>COOPERATE WITH CLARITY</span></div></div><h1>让每一次合作，<br>都有共同确认的方向。</h1><p>把计划、分工与资金边界说明白。采购全员知情，重要决定逐人确认。你不必每天盯人，但不再错过关键决定。</p><div class="auth-marks"><span>✓ 多人会签</span><span>✓ 阶段预算</span><span>✓ 审计留痕</span></div></section><section class="auth-form-wrap"><div class="auth-card"><h2>${joining?'加入合作项目':setup?'初始化你的工作空间':'欢迎回到合作执行台'}</h2><p>${joining?`项目：${e(invite.name)} · 邀请邮箱：${e(invite.email)}`:setup?'第一次使用，需要部署时配置的初始化口令。':'使用自己的账号登录，不代替其他合伙人表态。'}</p><form id="auth-form" data-mode="${mode}">${setup?fieldHtml({name:'token',label:'初始化口令 BOOTSTRAP_TOKEN',type:'password'}):''}${joining||setup?fieldHtml({name:'name',label:'你的姓名'}):''}${!joining?fieldHtml({name:'email',label:setup?'管理员邮箱':'用户名或邮箱',type:setup?'email':'text',autocomplete:'username'}):''}${fieldHtml({name:'password',label:joining?'设置账号密码（已有账号请输入原密码）':'账号密码',type:'password',help:setup||joining?'新密码12–128字符。邀请账号用自己的密码，不与伙伴共用。':''})}${joining?fieldHtml({name:'mfaCode',label:'已有账号绑定了验证器时，填写动态验证码或恢复码',required:false,autocomplete:'one-time-code',maxLength:100}):''}<div id="auth-error"></div><button type="submit" class="btn primary">${joining?'确认加入项目':setup?'初始化并登录':'登录工作空间'}</button></form><p class="auth-footer">账号由初始化或项目邀请建立，不开放任意注册。<br>密码遗失可由系统管理员重置临时密码，首登须改密，不能绕过其他合伙人的会签。</p></div></section></div>`;}
app.addEventListener('submit',async event=>{if(event.target.id!=='auth-form')return;event.preventDefault();const form=event.target,button=form.querySelector('button[type=submit]');button.disabled=true;const a=Object.fromEntries(new FormData(form)),mode=form.dataset.mode;if(mode==='invite')a.token=routeHash().invite;try{const result=await api(mode==='invite'?'/api/auth/accept':mode==='bootstrap'?'/api/auth/bootstrap':'/api/auth/login',{method:'POST',body:a});S.user=result.user;S.csrf=result.csrf;if(mode==='invite')history.replaceState(null,'',location.pathname);await afterLogin(result.projectId);}catch(err){$('#auth-error').innerHTML=`<div class="field-error" role="alert">${e(err.message)}</div>`;}finally{button.disabled=false;}});
async function afterLogin(preferred=null){if(S.user.mfaRequired){SECURITY.renderChallenge();return;}if(S.user.mustChangePassword){renderPasswordRequired();return;}S.projects=(await api('/api/projects')).projects;const r=routeHash(),pid=preferred||r.pid||localStorage.getItem('coop.project');if(pid&&S.projects.some(p=>p.id===pid))await selectProject(pid);else if(S.projects.some(p=>(p.lifecycle||'active')==='active'))await selectProject(S.projects.find(p=>(p.lifecycle||'active')==='active').id);if(S.project&&r.tab)await navigate(r.tab);if(S.user.systemRole==='admin'&&!S.projects.length){try{await ADMIN.open();return;}catch(err){if(err.code!=='MFA_SETUP_REQUIRED')throw err;S.adminMode=false;render();toast('请先打开账号安全绑定验证器，再进入管理后台',true);return;}}render();}
async function boot(){try{const route=routeHash();if(route.invite){const invite=await api('/api/invite?token='+encodeURIComponent(route.invite));renderAuth('invite',invite);return;}try{const r=await api('/api/auth/me');S.user=r.user;S.csrf=r.csrf;await afterLogin();}catch(err){if(err.status!==401)throw err;const status=await api('/api/auth/status');renderAuth(status.initialized?'login':'bootstrap');}}catch(err){app.innerHTML=`<div class="loading"><h2>暂时无法打开工作空间</h2><p>${e(err.message)}</p><p>请检查配置和网络后刷新页面。</p></div>`;}}
window.addEventListener('hashchange',async()=>{const r=routeHash();if(r.invite)await boot();else if(S.user&&!S.user.mfaRequired&&!S.user.mustChangePassword&&r.pid){await selectProject(r.pid);if(r.tab)await navigate(r.tab);}});
const READ_ACTIONS=new Set(['supervision-refresh','supervision-report-view','supervision-funding-view','supervision-issue-view','menu','close-menu','logout','profile','security-open','continuity-view','new-project','project-filter','purchase-open','purchase-back','audit-verify','export-project','export-csv','export-ledger','notice-open']);
const SECURITY=createSecurityUI({S,api,e,app,showForm,showInfo,reauth,openAccessibleDialog,afterLogin,toast});
const SUPERVISION=createSupervisionUI({S,e,act,showForm,showInfo,btn,panel,money,shortDate,toCents,amountInput,isPartner,toast,navigate,selectProject});
const CONTINUITY=createContinuityUI({S,e,act,showForm,showInfo,btn,panel,money,shortDate,toCents,amountInput,isPartner,toast});
const ADMIN=createAdminUI({S,e,api,reauth,showForm,showInfo,render,btn,panel,money,shortDate,toast,toCents,amountInput,openSecurity:()=>SECURITY.open()});
const AI=createAiUI({S,e,api,act,reauth,showForm,showInfo,render,btn,panel,pageHead,money,shortDate,toCents,amountInput,isPartner,mOptions,stageOptions,toast});
boot();
